import AppKit
import ComposableArchitecture

// MARK: - SoundsClient

/// Plays one bundled cue by resource name, such as `drop-activate`. The files live in `Sounds/`
/// and are generated by `scripts/generate_sound_themes.py`.
@DependencyClient struct SoundsClient {
  var play: @Sendable (String) async -> Void
}

// MARK: DependencyKey

extension SoundsClient: DependencyKey {
  static let liveValue = Self(play: { name in await BundledSounds.play(name) })
  /// Silence is the right behaviour for tests that are not about sounds; the ones that are inject
  /// a recorder.
  static let testValue = Self(play: { _ in })
}

extension DependencyValues {
  var sounds: SoundsClient {
    get { self[SoundsClient.self] }
    set { self[SoundsClient.self] = newValue }
  }
}

// MARK: - BundledSounds

private enum BundledSounds {
  // MARK: Internal

  @MainActor static func play(_ name: String) {
    currentSound?.stop()
    guard let url = Bundle.main.url(forResource: name, withExtension: "wav"),
          let sound = NSSound(contentsOf: url, byReference: true)
    else {
      preconditionFailure("Bundled sound missing: \(name).wav")
    }
    currentSound = sound
    sound.play()
  }

  // MARK: Private

  @MainActor private static var currentSound: NSSound?
}
